/// Returns an upper bound on the difference between any two elements in the array `a`,
/// i.e. the difference between the maximum and minimum elements.
/// 
/// # Panics
///
/// Panics if `a.len() < 2`.
fn MaxDifference(a: Vec<i32>) -> i32 {
    assert!(a.len() >= 2, "Input array must contain at least two elements");

    // Initialize min and max with the first element
    let mut iter = a.into_iter();
    let first = iter.next().unwrap();
    let (mut min_val, mut max_val) = (first, first);

    // Update min and max as we traverse
    for v in iter {
        if v < min_val {
            min_val = v;
        } else if v > max_val {
            max_val = v;
        }
    }

    max_val - min_val
}

